def diameter_brute(root):
    if root is None:
        return 0
    best = 0
    def visit(node):
        nonlocal best
        if node is None:
            return
        through = depth(node.left) + depth(node.right)      # recomputes depth from scratch each time
        best = max(best, through)
        visit(node.left)
        visit(node.right)
    visit(root)
    return best

