def diameter_of_binary_tree(root):
    best = [0]
    def depth(node):
        if node is None:
            return 0
        left = depth(node.left)                              # computed ONCE per node
        right = depth(node.right)                             # computed ONCE per node
        best[0] = max(best[0], left + right)                  # update running diameter here
        return 1 + max(left, right)
    depth(root)
    return best[0]

