int best = 0;

int depth(TreeNode* node) {
    if (!node) return 0;
    int left = depth(node->left);                                 // computed ONCE per node
    int right = depth(node->right);                                // computed ONCE per node
    best = max(best, left + right);                                  // update running diameter here
    return 1 + max(left, right);
}

int diameterOfBinaryTree(TreeNode* root) {
    best = 0;
    depth(root);
    return best;
